class Auto(object):
    """The ``Auto`` specifier type enables automatic target resolution in glom.

    When encountered, ``Auto`` will be replaced by the current target value,
    allowing for dynamic specification construction based on the data being
    processed. This is useful for streaming operations and variable capture.

    >>> target = {'a': 1}
    >>> glom(target, Auto)
    {'a': 1}
    """
    def __repr__(self):
        return 'Auto'

    def glomit(self, target, scope):
        return target

